// EDIT THESE VALUES (one place per workflow). No other node needs changing.
// The poke key is not here: it lives only in the "Poke secret" credential (decision 316).
const supabaseUrl = 'https://YOUR-PROJECT.supabase.co';      // Supabase project URL
const pokeUrl = 'https://YOUR-N8N/webhook/sme-poke';          // WF4 "Action runner" production webhook URL

return [{ json: {
  supabaseUrl: supabaseUrl.replace(/\/+$/, ''),
  pokeUrl,
} }];

// Collect the queued actions (the HTTP node returns one item per action, or one empty item).
const actions = $input.all().map(i => i.json).filter(a => a && a.id);
return [{ json: {
  actions: actions.map(a => ({ id: a.id, action: a.action })),
  runCheck: actions.some(a => a.action === 'run_check_now'),
} }];

// Build the Discord message payload from the claimed row. No decisions: the database wrote the text.
const m = $input.first().json;
let text = String(m.body_text || m.subject || '');
if (text.length > 2000) text = text.slice(0, 1999) + '…';

const buttons = (Array.isArray(m.buttons) ? m.buttons : []).filter(b => b && b.url).slice(0, 25);
const rows = [];
for (let i = 0; i < buttons.length; i += 5) {
  rows.push({
    type: 1,
    components: buttons.slice(i, i + 5).map(b => ({
      type: 2, style: 5, label: String(b.label || 'Open').slice(0, 80), url: String(b.url),
    })),
  });
}

// Discord refuses a message that lists the same user twice (for example an instructor who is also on the team).
const users = [...new Set((Array.isArray(m.mention_user_ids) ? m.mention_user_ids : []).map(String))].slice(0, 100);
const payload = {
  content: text,
  allowed_mentions: { parse: [], users },
  // No link preview cards (Discord flag SUPPRESS_EMBEDS): the message stays short and clean.
  flags: 4,
};
if (rows.length) payload.components = rows;
// Discord drops a second post with the same nonce, so a retry after a lost answer never posts twice.
payload.nonce = String(m.id).replace(/-/g, '').slice(0, 25);
payload.enforce_nonce = true;

return [{ json: {
  message_id: m.id,
  // Decision 348: the answer names the claim it belongs to, so a late answer changes nothing.
  claimed_at: m.claimed_at || null,
  dmUserId: m.discord_dm_user_id || null,
  targetChannelId: m.discord_channel_id || null,
  payload,
} }];

function describeFailure(r) {
  // r is either { error } (network failure / thrown error) or { statusCode, body } (full HTTP response)
  if (r.error) {
    const e = typeof r.error === 'object' ? r.error : { message: String(r.error) };
    const msg = String(e.message || e.description || JSON.stringify(e));
    const status = Number(e.httpCode || e.status || e.statusCode || (msg.match(/\b([45]\d\d)\b/) || [])[1] || 0);
    return { text: ((status ? status + ' ' : '') + msg).slice(0, 1000), permanent: status >= 400 && status < 500 && status !== 429 && status !== 401 };
  }
  const status = Number(r.statusCode || 0);
  const b = r.body && typeof r.body === 'object' ? r.body : {};
  let text = status + ' ' + (b.message || r.statusMessage || (typeof r.body === 'string' ? r.body.slice(0, 300) : ''));
  if (b.code) text += ' (Discord code ' + b.code + ')';
  if (b.errors) text += ' ' + JSON.stringify(b.errors).slice(0, 500);
  if (status === 429 && b.retry_after) text += ' (rate limited, retry after ' + b.retry_after + 's)';
  return { text: text.trim().slice(0, 1000), permanent: status >= 400 && status < 500 && status !== 429 && status !== 401 && b.code !== 40001 };
}

const retryAfter = (r) => { const s = r && r.statusCode === 429 && r.body && Number(r.body.retry_after); return s > 0 ? Math.ceil(s) : null; };
const prep = $('Prepare Discord').first().json;
const r = $input.first().json;
if (!r.error && r.statusCode >= 200 && r.statusCode < 300 && r.body && r.body.id) {
  return [{ json: { ...prep, targetChannelId: r.body.id, ready: true } }];
}
const f = describeFailure(r);
return [{ json: {
  ready: false,
  p_message_id: prep.message_id, p_ok: false, p_external_id: null,
  p_error: 'Could not open DM channel: ' + f.text, p_permanent: f.permanent,
  p_retry_after: retryAfter(r), p_claimed_at: prep.claimed_at,
} }];

function describeFailure(r) {
  // r is either { error } (network failure / thrown error) or { statusCode, body } (full HTTP response)
  if (r.error) {
    const e = typeof r.error === 'object' ? r.error : { message: String(r.error) };
    const msg = String(e.message || e.description || JSON.stringify(e));
    const status = Number(e.httpCode || e.status || e.statusCode || (msg.match(/\b([45]\d\d)\b/) || [])[1] || 0);
    return { text: ((status ? status + ' ' : '') + msg).slice(0, 1000), permanent: status >= 400 && status < 500 && status !== 429 && status !== 401 };
  }
  const status = Number(r.statusCode || 0);
  const b = r.body && typeof r.body === 'object' ? r.body : {};
  let text = status + ' ' + (b.message || r.statusMessage || (typeof r.body === 'string' ? r.body.slice(0, 300) : ''));
  if (b.code) text += ' (Discord code ' + b.code + ')';
  if (b.errors) text += ' ' + JSON.stringify(b.errors).slice(0, 500);
  if (status === 429 && b.retry_after) text += ' (rate limited, retry after ' + b.retry_after + 's)';
  return { text: text.trim().slice(0, 1000), permanent: status >= 400 && status < 500 && status !== 429 && status !== 401 && b.code !== 40001 };
}

const retryAfter = (r) => { const s = r && r.statusCode === 429 && r.body && Number(r.body.retry_after); return s > 0 ? Math.ceil(s) : null; };
const prep = $('Prepare Discord').first().json;
const r = $input.first().json;
if (!prep.targetChannelId && !prep.dmUserId) {
  return [{ json: { p_message_id: prep.message_id, p_ok: false, p_external_id: null,
    p_error: 'No Discord channel or user on this message', p_permanent: true, p_claimed_at: prep.claimed_at } }];
}
if (!r.error && r.statusCode >= 200 && r.statusCode < 300) {
  return [{ json: { p_message_id: prep.message_id, p_ok: true, p_external_id: (r.body && r.body.id) || null,
    p_error: null, p_permanent: false, p_claimed_at: prep.claimed_at } }];
}
const f = describeFailure(r);
return [{ json: { p_message_id: prep.message_id, p_ok: false, p_external_id: null, p_error: f.text, p_permanent: f.permanent,
  p_retry_after: retryAfter(r), p_claimed_at: prep.claimed_at } }];

const m = $input.first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const html = m.body_html || ('<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.5">'
  + esc(m.body_text || '').replace(/\r?\n/g, '<br>') + '</div>');
return [{ json: { message_id: m.id, claimed_at: m.claimed_at || null, to: m.to_address || '', subject: m.subject || '(no subject)', html } }];

const prep = $('Prepare email').first().json;
const r = $input.first().json;
if (!r.error && r.id) {
  return [{ json: { p_message_id: prep.message_id, p_ok: true, p_external_id: r.id, p_error: null, p_permanent: false, p_claimed_at: prep.claimed_at } }];
}
const e = r.error && typeof r.error === 'object' ? r.error : { message: r.error ? String(r.error) : 'Gmail returned no message id' };
const text = [e.message, e.description].filter(Boolean).join(' — ').slice(0, 1000) || 'Gmail send failed';
const temporary = /invalid_grant|invalid_client|unauthorized|\b401\b|429|rate|quota|limit|timeout|timed out|ECONN|ENOTFOUND|EAI_AGAIN|5\d\d|backend error|unavailable/i.test(text);
const permanent = !temporary && (!prep.to || /invalid|bad request|\b400\b|recipient address/i.test(text));
return [{ json: { p_message_id: prep.message_id, p_ok: false, p_external_id: null, p_error: text, p_permanent: permanent, p_claimed_at: prep.claimed_at } }];

const plan = $('Plan actions').first().json;
if (!plan.actions || !plan.actions.length) return [];

const errText = j => j && j.error ? (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))) : null;
let engine = null, engineError = null, claimError = null, claimed = 0;
try { engine = $('Run engine').first().json; engineError = errText(engine); } catch (e) { /* engine not run */ }
try { claimError = errText($('Claim messages').first().json); } catch (e) { /* not run */ }
try { claimed = $('Keep claimed rows').all().length; } catch (e) { claimed = 0; }

return plan.actions.map(a => {
  const failed = (a.action === 'run_check_now' && engineError) || claimError;
  return { json: {
    p_action_id: a.id,
    p_ok: !failed,
    p_result: { claimed_messages: claimed, engine: a.action === 'run_check_now' && !engineError ? engine : null },
    p_error: failed ? String(engineError || claimError).slice(0, 1000) : null,
  } };
});

// One item per Discord call. Each call remembers its piece of work and what it is for.
// n8n splits the list the database returns into one item per piece of work, so read them all.
const items = $input.all().map((i) => i.json);
const raw = items[0];
const work = Array.isArray(raw) ? raw : (Array.isArray(raw?.data) ? raw.data : items.filter((w) => w && w.action_id));
const out = [];
for (const w of work) {
  if (w.action === 'discord_servers') {
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'guilds', path: '/users/@me/guilds' } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'me', path: '/users/@me' } });
  }
  else if (w.action === 'discord_server') {
    if (!w.server_id) { out.push({ json: { action_id: w.action_id, action: w.action, key: 'guild', path: null } }); continue; }
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'guild', path: `/guilds/${w.server_id}` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'channels', path: `/guilds/${w.server_id}/channels` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'members', path: `/guilds/${w.server_id}/members/search?query=a&limit=1` } });
    // The bot's roles and the server's roles: the database works out where the bot may post.
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'roles', path: `/guilds/${w.server_id}/roles` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'me', path: '/users/@me' } });
    if (w.bot_user_id) out.push({ json: { action_id: w.action_id, action: w.action, key: 'bot', path: `/guilds/${w.server_id}/members/${w.bot_user_id}` } });
  } else if (w.action === 'discord_channel') {
    // An instructor's channel, checked before it is saved (decision 330): the channel and its overwrites, the
    // server's roles, the bot's and the instructor's roles. The database works out what each of them may do.
    if (!w.channel_id || !w.server_id) { out.push({ json: { action_id: w.action_id, action: w.action, key: 'channel', path: null } }); continue; }
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'channel', path: `/channels/${w.channel_id}` } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'roles', path: `/guilds/${w.server_id}/roles` } });
    if (w.bot_user_id) out.push({ json: { action_id: w.action_id, action: w.action, key: 'bot', path: `/guilds/${w.server_id}/members/${w.bot_user_id}` } });
    else out.push({ json: { action_id: w.action_id, action: w.action, key: 'me', path: '/users/@me' } });
    out.push({ json: { action_id: w.action_id, action: w.action, key: 'member', path: `/guilds/${w.server_id}/members/${w.user_id}` } });
  } else if (w.action === 'discord_member') {
    const servers = w.username ? (w.servers || []) : [];
    if (servers.length === 0) out.push({ json: { action_id: w.action_id, action: w.action, key: 'none', path: null } });
    for (const s of servers) out.push({ json: { action_id: w.action_id, action: w.action, key: 'search', server_id: s, username: w.username,
      path: `/guilds/${s}/members/search?query=${encodeURIComponent(w.username)}&limit=1000` } });
  }
}
return out;

// Put the answers of each piece of work together, in the shape record_discord_result reads.
const calls = $('Plan calls').all().map((i) => i.json);
const answers = $input.all().map((i) => i.json);
const byAction = new Map();
calls.forEach((c, n) => {
  const a = answers[n] || {};
  const status = c.path ? (a.statusCode ?? 0) : 404;
  const body = status >= 200 && status < 300 ? a.body : undefined;
  const r = byAction.get(c.action_id) || { action_id: c.action_id, result: {} };
  if (c.key === 'search') (r.result.searches ||= []).push({ server_id: c.server_id, status, body: body || [] });
  else if (c.key === 'none') r.result.searches ||= [];
  else if (c.key === 'members') r.result.members = { status };
  else r.result[c.key] = { status, body };
  byAction.set(c.action_id, r);
});
return [...byAction.values()].map((r) => ({ json: { p_action_id: r.action_id, p_result: r.result } }));

// Parse each Gmail message into one database call. Parsing only; the database decides what it means.
// Only mail about this system is handled: replies sent to the +scheduling Reply-To address, and bounces
// of emails this system sent (they quote that address). Everything else in the shared inbox is skipped.
const SYS = 'scheduling-mailbox+scheduling@yourcompany.com';
function hdr(m, name) {
  const h = m.headers; const want = name.toLowerCase(); let v;
  if (Array.isArray(h)) {
    const f = h.find(x => String(x.name || x.key || '').toLowerCase() === want);
    v = f && (f.value || f.line);
  } else if (h && typeof h === 'object') {
    for (const k of Object.keys(h)) if (k.toLowerCase() === want) v = h[k];
  }
  if (v == null) return '';
  v = typeof v === 'object' ? (v.text || v.value || JSON.stringify(v)) : String(v);
  return v.replace(new RegExp('^' + want + ':\\s*', 'i'), '').trim();
}
function stripQuoted(t) {
  const lines = String(t || '').replace(/\r\n/g, '\n').split('\n');
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i];
    if (/^\s*>/.test(l)) break;
    if (/^-{2,}\s*Original Message\s*-{2,}/i.test(l)) break;
    if (/^On\s.+/.test(l) && /wrote:\s*$/.test(l + ' ' + (lines[i + 1] || ''))) break;
    out.push(l);
  }
  return out.join('\n').trim() || String(t || '').trim();
}
function failedRecipient(m, text) {
  const x = hdr(m, 'x-failed-recipients');
  if (x) return x.split(',')[0].trim();
  const pats = [
    /Final-Recipient:\s*rfc822;\s*<?([^\s<>;]+@[^\s<>;]+)/i,
    /Original-Recipient:\s*rfc822;\s*<?([^\s<>;]+@[^\s<>;]+)/i,
    /delivered to\s+<?([^\s<>]+@[^\s<>]+)/i,
  ];
  for (const p of pats) { const r = text.match(p); if (r) return r[1].replace(/[>.,;:]+$/, ''); }
  const to = String((m.to && m.to.text) || hdr(m, 'to')).toLowerCase();
  const skip = /mailer-daemon|postmaster|no-?reply|@google\.com$|@googlemail\.com$|^scheduling-mailbox/i;
  const all = text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
  return all.find(a => !skip.test(a) && !to.includes(a.toLowerCase())) || '';
}

const out = [];
for (const item of $input.all()) {
  const m = item.json || {};
  if (!m.id) continue;
  const from = String((m.from && (m.from.text || (m.from.value && m.from.value[0] && m.from.value[0].address))) || hdr(m, 'from') || m.From || '');
  const subject = String(m.subject || hdr(m, 'subject') || m.Subject || '');
  const text = String(m.text || (m.html ? String(m.html).replace(/<[^>]+>/g, ' ') : '') || m.snippet || '');
  const received = m.date ? new Date(m.date) : null;
  const isBounce = /mailer-daemon|postmaster/i.test(from)
    || /delivery status notification|undeliverable|undelivered mail|mail delivery (failed|failure|subsystem)/i.test(subject);
  const addressedTo = (JSON.stringify(m.to || '') + ' ' + JSON.stringify(m.cc || '') + ' ' + hdr(m, 'delivered-to') + ' ' + hdr(m, 'to')).toLowerCase();
  if (isBounce ? !text.toLowerCase().includes(SYS) : !addressedTo.includes(SYS)) continue;
  if (isBounce) {
    out.push({ json: { gmail_id: m.id, rpc: 'record_bounce', args: {
      p_email: failedRecipient(m, text),
      p_external_id: m.id,
      p_detail: (subject + ': ' + text.replace(/\s+/g, ' ')).slice(0, 500),
      // SEC 9 (decision 311): the database counts a bounce only in the thread of an email it sent to that address.
      p_thread_id: m.threadId || null,
      p_report: /multipart\/report/i.test(hdr(m, 'content-type')) && /delivery-status/i.test(hdr(m, 'content-type')),
    } } });
  } else {
    // Review R19: out of office, bulk and other automatic mail is kept and logged, never a task.
    const auto = hdr(m, 'auto-submitted').toLowerCase();
    const automatic = (auto !== '' && auto !== 'no')
      || /^(bulk|junk|auto_reply)/i.test(hdr(m, 'precedence'))
      || hdr(m, 'x-autoreply') !== '' || hdr(m, 'x-autorespond') !== ''
      || /^(automatic reply|auto ?reply|out of( the)? office)\b/i.test(subject.trim());
    out.push({ json: { gmail_id: m.id, rpc: 'record_inbound_message', args: {
      p_channel: 'Email',
      p_from: from,
      p_subject: subject || null,
      p_body: stripQuoted(text).slice(0, 5000),
      p_external_id: m.id,
      p_received_at: received && !isNaN(received) ? received.toISOString() : null,
      p_summary: null,
      // Finding 38 (decision 345): in a Testing domain the reply is matched by the thread the app's email started.
      p_thread_id: m.threadId || null,
      p_automatic: automatic,
    } } });
  }
}
return out;

// Keep only messages written by the instructor who owns the channel, oldest first.
const watch = $('Get watchlist').all();
const cutoff = Date.now() - 3 * 24 * 3600 * 1000;
const byId = (a, b) => (BigInt(a.id) < BigInt(b.id) ? -1 : BigInt(a.id) > BigInt(b.id) ? 1 : 0);
const out = [];
$input.all().forEach((item, idx) => {
  const w = (watch[(item.pairedItem && item.pairedItem.item) ?? idx] || {}).json || {};
  const r = item.json || {};
  if (!w.channel_id || r.error || r.statusCode !== 200 || !Array.isArray(r.body)) return;
  for (const m of r.body.slice().sort(byId)) {
    if (!m.author || String(m.author.id) !== String(w.discord_user_id)) continue;
    if (!w.last_message_id && Date.parse(m.timestamp) < cutoff) continue;
    const parts = [m.content || ''];
    for (const a of m.attachments || []) parts.push('[attachment] ' + a.url);
    // Review R15: never dropped silently (for example if the bot may not read message text).
    const body = parts.join('\n').trim() || '[A message with no readable text. Open the channel in Discord to read it.]';
    out.push({ json: { channel_id: w.channel_id, rpc: 'record_inbound_message', args: {
      p_channel: 'Discord',
      p_from: String(m.author.id),
      p_subject: null,
      p_body: body.slice(0, 5000),
      p_external_id: String(m.id),
      p_received_at: m.timestamp || null,
      p_summary: null,
      // Review R8: the channel it was posted in decides whose reply it is.
      p_channel_id: w.channel_id,
    } } });
  }
});
return out;

// Newest message id per channel. Skip channels that could not be read or where a record failed.
const watch = $('Get watchlist').all();
const failed = new Set();
try {
  const picked = $('Pick instructor replies').all();
  $('Record Discord reply').all().forEach((r, i) => {
    if (r.json && r.json.error && picked[i]) failed.add(picked[i].json.channel_id);
  });
} catch (e) { /* no replies were recorded this run */ }
const out = [];
$input.all().forEach((item, idx) => {
  const w = (watch[(item.pairedItem && item.pairedItem.item) ?? idx] || {}).json || {};
  const r = item.json || {};
  if (!w.channel_id || r.error || r.statusCode !== 200 || !Array.isArray(r.body) || !r.body.length) return;
  if (failed.has(w.channel_id)) return;
  const newest = r.body.map(m => String(m.id)).reduce((a, b) => (BigInt(b) > BigInt(a) ? b : a));
  out.push({ json: { p_channel_id: w.channel_id, p_last_message_id: newest } });
});
return out;

// Review R15: a channel the bot cannot read is logged (once a run) instead of being skipped silently.
const watch = $('Get watchlist').all();
const bad = [];
$input.all().forEach((item, idx) => {
  const w = (watch[(item.pairedItem && item.pairedItem.item) ?? idx] || {}).json || {};
  const r = item.json || {};
  if (!w.channel_id || (r.statusCode === 200 && Array.isArray(r.body))) return;
  bad.push('channel ' + w.channel_id + ': ' + (r.statusCode || (r.error && r.error.message) || 'no answer'));
});
return bad.length ? [{ json: { error: 'Discord channels could not be read (' + bad.length + '): ' + bad.slice(0, 5).join('; ') } }] : [];
